// Normalise whatever the trigger gave us into: json.file_name + binary.data
const bin = $input.item.binary || {};
const key = Object.keys(bin)[0];
if (!key) throw new Error('No file received - upload or drop a PDF invoice.');
const file = bin[key];
const name = file.fileName || 'invoice.pdf';
const looksPdf = String(file.mimeType || '').includes('pdf') || /\.pdf$/i.test(name);
if (!looksPdf) throw new Error('Only PDF files are supported, got: ' + name);
return {
  json: { file_name: name, source: $json.event ? 'folder' : 'form' },
  binary: { data: file },
};

