const cfg = $('Config').first().json;
const fileName = $('Prepare PDF').first().json.file_name;
const pdfText = String($('Extract PDF Text').first().json.text || '');

// ---------- 1. Read the LLM answer (JSON mode, but we still parse defensively) ----------
const msg = $json.choices && $json.choices[0] && $json.choices[0].message;
const raw = (msg && msg.content) || '';
let inv = {};
const problems = [];
try {
  inv = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
} catch (e) {
  problems.push('AI did not return valid JSON - extraction failed');
}
if (pdfText.trim().length < 20) {
  problems.push('Almost no text found in the PDF (scanned image?)');
}

// ---------- 2. Normalise the fields ----------
const toNum = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = typeof v === 'number' ? v : parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const round2 = (n) => Math.round(n * 100) / 100;

const lineItems = (Array.isArray(inv.line_items) ? inv.line_items : []).map((li) => ({
  description: String((li && li.description) || ''),
  quantity: toNum(li && li.quantity),
  unit_price: toNum(li && li.unit_price),
  amount: toNum(li && li.amount),
}));

const rec = {
  vendor: inv.vendor ? String(inv.vendor).trim() : null,
  invoice_number: inv.invoice_number ? String(inv.invoice_number).trim() : null,
  invoice_date: inv.invoice_date ? String(inv.invoice_date).trim() : null,
  currency: inv.currency ? String(inv.currency).trim().toUpperCase() : null,
  subtotal: toNum(inv.subtotal),
  tax: toNum(inv.tax),
  total: toNum(inv.total),
  summary: inv.summary ? String(inv.summary).trim() : '',
};

// ---------- 3. Validation rules ----------
if (!rec.vendor) problems.push('Vendor missing');
if (!rec.invoice_number) problems.push('Invoice number missing');
if (rec.total === null) problems.push('Total missing');
else if (rec.total <= 0) problems.push('Total is zero or negative');

const lineSum = lineItems.reduce((s, li) => s + (li.amount || 0), 0);
if (rec.subtotal !== null && lineItems.length > 0 && Math.abs(lineSum - rec.subtotal) > 0.02) {
  problems.push('Line items (' + round2(lineSum) + ') do not add up to subtotal (' + rec.subtotal + ')');
}
if (rec.subtotal !== null && rec.total !== null) {
  const expected = round2(rec.subtotal + (rec.tax || 0));
  if (Math.abs(expected - rec.total) > 0.02) {
    problems.push('Subtotal + tax (' + expected + ') does not equal total (' + rec.total + ')');
  }
}
if (rec.invoice_date) {
  const t = Date.parse(rec.invoice_date);
  if (isNaN(t)) problems.push('Invoice date is not a valid date');
  else if (t > Date.now() + 86400000) problems.push('Invoice date is in the future');
}

// ---------- 4. Routing decision ----------
const limit = Number(cfg.auto_approve_limit);
const overLimit = rec.total !== null && rec.total > limit;
const reasons = problems.concat(overLimit ? ['Total exceeds auto-approve limit (' + limit + ')'] : []);
const needsApproval = reasons.length > 0;

// ---------- 5. Message for the approver ----------
const money = (rec.currency ? rec.currency + ' ' : '') + (rec.total !== null ? rec.total.toFixed(2) : 'n/a');
const approvalText = [
  '🧾 Invoice needs your approval',
  '',
  'Vendor: ' + (rec.vendor || '?'),
  'Invoice #: ' + (rec.invoice_number || '?'),
  'Date: ' + (rec.invoice_date || '?'),
  'Total: ' + money,
  'Summary: ' + (rec.summary || '-'),
  '',
  reasons.length ? '⚠️ Flags:\n- ' + reasons.join('\n- ') : '✅ All validation checks passed',
  '',
  'File: ' + fileName,
].join('\n');

return {
  json: {
    decision_id: Math.random().toString(36).slice(2, 8),
    file_name: fileName,
    ...rec,
    line_items: lineItems,
    validation_status: problems.length ? 'FAIL' : 'PASS',
    validation_notes: problems.join('; '),
    review_reasons: reasons.join('; '),
    needs_approval: needsApproval,
    approval_text: approvalText,
  },
};

const r = $json;
const money = (r.currency ? r.currency + ' ' : '') + (r.total === null || r.total === undefined ? 'n/a' : Number(r.total).toFixed(2));
const has = (v) => v !== null && v !== undefined;
const lines = (Array.isArray(r.line_items) ? r.line_items : []).map((li) =>
  '- ' + (li.description || 'item') + (has(li.quantity) ? ' x ' + li.quantity : '') + (has(li.unit_price) ? ' @ ' + li.unit_price : '') + ' = ' + (has(li.amount) ? li.amount : '?'));

const md = [
  '**Vendor:** ' + (r.vendor || '?'),
  '**Invoice #:** ' + (r.invoice_number || '?'),
  '**Invoice date:** ' + (r.invoice_date || '?'),
  '**Total:** ' + money + (has(r.subtotal) ? ' (subtotal ' + r.subtotal + ', tax ' + (has(r.tax) ? r.tax : 0) + ')' : ''),
  '**Validation:** ' + (r.validation_status || '?') + (r.validation_notes ? ' - ' + r.validation_notes : ''),
  r.review_reasons ? '**Review reasons:** ' + r.review_reasons : '',
  '**Summary:** ' + (r.summary || '-'),
  '',
  '**Line items**',
  lines.length ? lines.join('\n') : '- none extracted',
  '',
  '_Source file: ' + (r.file_name || '?') + ' | created by n8n_',
].filter((l, i, a) => !(l === '' && i > 0 && a[i - 1] === '')).join('\n');

return {
  json: {
    ...r,
    task_name: (r.invoice_number || 'no number') + ' | ' + (r.vendor || 'unknown vendor') + ' | ' + money,
    task_markdown: md,
    task_priority: r.validation_status === 'FAIL' ? 2 : null,
  },
};

// ClickUp's reply replaced our item, so put the original PDF back on it for the upload step
return {
  json: { task_id: $json.id, task_url: $json.url },
  binary: $('Prepare PDF').first().binary,
};

// Rebuild one item that has everything later steps need: invoice fields + ClickUp task id/url
const rec = $('Build ClickUp Task').first().json;
const task = $('Create ClickUp Task').first().json;
return { json: { ...rec, task_id: task.id, task_url: task.url, attach_ok: !$json.error } };

const ctx = $('Task Context').first().json;
const base = String($json.link_base || '');
const link = (action) => base + (base.includes('?') ? '&' : '?') + 'action=' + action;
const esc = (s) => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const btn = (label, action, color) =>
  '<a href="' + link(action) + '" style="display:inline-block;padding:12px 20px;margin:4px 8px 4px 0;background:' + color +
  ';color:#ffffff;text-decoration:none;border-radius:6px;font-weight:bold;font-family:Arial,sans-serif;font-size:14px;">' + label + '</a>';

const money = (ctx.currency ? ctx.currency + ' ' : '') + (ctx.total === null || ctx.total === undefined ? 'n/a' : ctx.total);
const html = [
  '<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:560px;">',
  '<pre style="font-family:Arial,sans-serif;font-size:14px;white-space:pre-wrap;margin:0 0 12px 0;">' + esc(ctx.approval_text) + '</pre>',
  '<p style="margin:0 0 16px 0;">ClickUp task: <a href="' + esc(ctx.task_url) + '">' + esc(ctx.task_url) + '</a></p>',
  '<p style="margin:0 0 12px 0;">' +
    btn('✅ Approve', 'approve', '#2e7d32') +
    btn('✏️ Request changes', 'changes', '#ef6c00') +
    btn('❌ Reject', 'reject', '#c62828') + '</p>',
  '<p style="color:#777;font-size:12px;margin:0;">Click once - the decision is recorded in ClickUp. The buttons open n8n, so use them on the computer that runs n8n.</p>',
  '</div>',
].join('');

return {
  json: {
    email_subject: 'Review needed: ' + (ctx.invoice_number || '?') + ' | ' + (ctx.vendor || 'unknown vendor') + ' | ' + money,
    email_html: html,
  },
};

const ctx = $('Task Context').first().json;
const cfg = $('Config').first().json;
// The item that resumed the Wait node. It has a 'query' object when a button was clicked,
// and no 'query' at all when the wait timed out.
const w = $('Wait for Review Click').first().json;
const action = String((w.query && w.query.action) || '').toLowerCase();
const who = cfg.approver_email;

const map = {
  approve: { decision: 'APPROVED', status: cfg.status_approved, text: 'Approved by ' + who + ' via the email button.' },
  changes: { decision: 'CHANGES_NEEDED', status: cfg.status_changes_needed,
             text: 'Changes requested by ' + who + ' via the email button.' + (ctx.review_reasons ? '\nFlagged at review: ' + ctx.review_reasons : '') + '\nPlease correct the invoice and upload it again.' },
  reject:  { decision: 'REJECTED', status: cfg.status_rejected, text: 'Rejected by ' + who + ' via the email button.' },
};
const m = map[action];

const decision = m ? m.decision : 'EXPIRED';
return {
  json: {
    ...ctx,
    decision,
    decided_by: m ? who : 'no response',
    decided_at: new Date().toISOString(),
    reviewer_comment: '',
    target_status: m ? m.status : cfg.status_reviewing,
    comment_text: m ? m.text : 'No valid decision received within ' + cfg.approval_timeout_minutes + ' minutes. Task left in "' + cfg.status_reviewing + '".',
  },
};

// Last node of the run: its 'page_html' is what the reviewer's browser shows after clicking a button
const f = $('Final Decision').first().json;
const esc = (s) => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const icon = { APPROVED: '✅', AUTO_APPROVED: '🤖', CHANGES_NEEDED: '✏️', REJECTED: '❌', EXPIRED: '⏰' }[f.decision] || 'ℹ️';
const page = '<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>' +
  '<body style="font-family:Arial,sans-serif;text-align:center;margin-top:15vh;color:#222;">' +
  '<h2>' + icon + ' Decision recorded</h2>' +
  '<p>Invoice <b>' + esc(f.invoice_number) + '</b> is now <b>' + esc(f.target_status) + '</b> in ClickUp.</p>' +
  '<p><a href="' + esc(f.task_url) + '">Open the task</a></p>' +
  '<p style="color:#777;">You can close this tab.</p></body></html>';
return { json: { page_html: page } };
